/// <summary>
/// Display pick list status
/// </summary>
/// <returns>WMSExpeditionStatus</returns>
public display WMSExpeditionStatus  displayPickListStatus()
{
    if (this.PickedQty == 0)
    {
        return WMSExpeditionStatus::Cancelled;
    }

    return WMSPickingRoute::find(this.PickingListNum).expeditionStatus;
}

/// <summary>
/// Display method for CCR Received
/// </summary>
/// <returns>boolean</returns>
public display boolean displayCCRReceived()
{
    METCCRTable     ccrTable;
    METTotes        totes;

    select firstonly ccrTable
        where ccrTable.SalesId == this.OrderNum;
    if(ccrTable)
    {
        return NoYes::Yes;
    }

    select firstonly totes
        where totes.SalesId == this.OrderNum;
    if(totes)
    {
        return NoYes::Yes;
    }
    return NoYes::No;
}

/// <summary>
/// CB626_TMSEngineSOPackingSlip exist method
/// </summary>
/// <param name = "_shipmentId">SO finalisation shipment id</param>
/// <param name = "_orderNum">Order number</param>
/// <param name = "_pickingListNum">FO picking list number</param>
/// <returns>True if the record exists; otherwise, false.</returns>
static boolean existOrderAndPickListNum(METShipmentId     _shipmentId,
                                        METOrderReference _orderNum,
                                        WMSPickingRouteID _pickingListNum)
{
    return _shipmentId && _orderNum && _pickingListNum && 
       (select firstonly METSalesOrderShipmentLoadLines
                   where METSalesOrderShipmentLoadLines.ShipmentId     == _shipmentId
                      && METSalesOrderShipmentLoadLines.OrderNum       == _orderNum
                      && METSalesOrderShipmentLoadLines.PickingListNum == _pickingListNum).RecId != 0;
}

/// <summary>
/// CB626_TMSEngineSOPackingSlip find method
/// </summary>
/// <param name = "_orderNum">Order number</param>
/// <param name = "_pickingListNum">FO picking list number</param>
/// <param name = "_forUpdate">Select record for update</param>
/// <returns>METSalesOrderShipmentLoadLines buffer</returns>
static METSalesOrderShipmentLoadLines findOrderAndPickListNum(METOrderReference _orderNum,
                                                              WMSPickingRouteID _pickingListNum,
                                                              boolean           _forUpdate = false)
{
    METSalesOrderShipmentLoadLines shipmentLine;

    if (_orderNum && _pickingListNum)
    {
        if (_forUpdate)
        {
            shipmentLine.selectForUpdate(_forUpdate);
        }

        select firstonly shipmentLine
                   where shipmentLine.OrderNum       == _orderNum
                      && shipmentLine.PickingListNum == _pickingListNum;
    }

    return shipmentLine;
}

/// <summary>
/// CB626_TMSEngineSOPackingSlip find shipment header from the line
