}

/// <summary>
/// Display method for customer instructions
/// </summary>
/// <returns><c>METCustomerInstruction details</c> record</returns>
public display METCustomerInstruction displayCustomerInstruction()
{
    SalesTable      salesTable = SalesTable::find(this.OrderNum);
    TransDate       defaultDate = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone());
    METWarehouseCarrierCustomerView     warehouseCustomerView;

    select firstonly CustomerInstruction from warehouseCustomerView 
        where warehouseCustomerView.CustAccount == SalesTable.custAccount       &&
            warehouseCustomerView.StartDate <= defaultDate                      &&
            warehouseCustomerView.EndDate >= defaultDate;

    return warehouseCustomerView.CustomerInstruction;

}

/// <summary>
/// Display method for warehouse instructions
/// </summary>
/// <returns><c>METWareHouseInstruction details</c> record</returns>
public display METWareHouseInstruction displayWarehouseInstruction()
{
    SalesTable      salesTable = SalesTable::find(this.OrderNum);
    TransDate       defaultDate = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone());
    METWarehouseCarrierCustomerView     warehouseCustomerView;

    select firstonly WarehouseInstruction from warehouseCustomerView
        where warehouseCustomerView.CustAccount == SalesTable.custAccount       &&
            warehouseCustomerView.StartDate <= defaultDate                      &&
            warehouseCustomerView.EndDate >= defaultDate;

    return warehouseCustomerView.WarehouseInstruction;

}

/// <summary>
/// Retrieves the lowest expedition status for all WmsPickingRoute records
/// associated with the current form context.
/// </summary>
/// <remarks>
/// This method filters WmsPickingRoute records by TransRefId and returns the
/// record with the lowest ExpeditionStatus value. ExpeditionStatus is an enum,
/// and ordering ascending ensures the smallest (earliest) status is selected.
///
/// The method is cached at the client for performance and can be bound directly
/// to a form control.
/// </remarks>
/// <returns>
/// WMSExpeditionStatus enum value representing the lowest expedition status
/// for the matching picking routes.
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
public display WMSExpeditionStatus getLowestExpeditionStatus()
{
    WmsPickingRoute wmsPickingRoute;

    select firstonly wmsPickingRoute
        order by wmsPickingRoute.ExpeditionStatus asc
            where wmsPickingRoute.TransRefId == this.OrderNum;

    return wmsPickingRoute.ExpeditionStatus;
}

